html:
{{ letter_head }}

{% set company_addr = frappe.db.get_value("Dynamic Link", {"link_doctype": "Company", "link_name": doc.company, "parenttype": "Address"}, "parent") %}
{% set company_address = frappe.get_doc("Address", company_addr) if company_addr else None %}
{% set customer_address = frappe.get_doc("Address", doc.customer_address) if doc.customer_address else None %}
{% set contact = frappe.get_doc("Contact", doc.contact_person) if doc.contact_person else None %}

{%- set _ns = namespace(qr_b64=None) %}
{%- if get_doc_qr_code is defined and get_doc_qr_code is callable %}
  {%- set _ns.qr_b64 = get_doc_qr_code(doc.doctype, doc.name) %}
{%- endif %}

<style>
.cgm-inv {
  font-family: Arial, Helvetica, sans-serif;
  color: #171717;
  font-size: 11px;
  line-height: 1.45;
  background: #fff;
}
.cgm-inv * { box-sizing: border-box; }

.cgm-header {
  width: 100%;
  border-collapse: collapse;
  margin: 0 0 14px;
}
.cgm-header td {
  vertical-align: middle;
  padding: 0;
}
.cgm-header .title {
  margin: 0;
  font-size: 26px;
  font-weight: 800;
  letter-spacing: 1.5px;
  text-transform: uppercase;
  color: #171717;
  line-height: 1.1;
}
.cgm-meta-table {
  border-collapse: collapse;
  margin-left: auto;
}
.cgm-meta-table td {
  padding: 2px 0;
  font-size: 10.5px;
  line-height: 1.55;
  white-space: nowrap;
}
.cgm-meta-table .lbl {
  color: #8b1a1a;
  font-weight: 700;
  padding-right: 14px;
  text-align: left;
}
.cgm-meta-table .val {
  color: #171717;
  font-weight: 700;
  text-align: right;
}

.cgm-rule {
  border: none;
  border-top: 1px solid #e5e5e5;
  margin: 0 0 14px;
}

.cgm-parties {
  width: 100%;
  border-collapse: collapse;
  margin: 0 0 14px;
}
.cgm-parties > tbody > tr > td {
  width: 50%;
  vertical-align: top;
  padding: 0 18px 0 0;
}
.cgm-parties > tbody > tr > td:last-child {
  padding: 0 0 0 18px;
}
.cgm-section-label {
  margin: 0 0 7px;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 1.2px;
  text-transform: uppercase;
  color: #8b1a1a;
}
.cgm-party-name {
  margin: 0 0 4px;
  font-size: 12px;
  font-weight: 700;
  color: #171717;
}
.cgm-party-line {
  margin: 0;
  font-size: 10.5px;
  color: #444;
  line-height: 1.55;
}
.cgm-party-line + .cgm-party-line { margin-top: 1px; }

.cgm-shipment-wrap {
  background: #fafafa;
  border-top: 1px solid #e5e5e5;
  border-bottom: 1px solid #e5e5e5;
  padding: 16px 18px;
  margin: 0 0 18px;
}
.cgm-shipment {
  width: 100%;
  border-collapse: collapse;
}
.cgm-shipment > tbody > tr > td {
  width: 50%;
  vertical-align: top;
  padding: 0 20px 0 0;
}
.cgm-shipment > tbody > tr > td:last-child {
  padding: 0 0 0 20px;
}
.cgm-kv {
  width: 100%;
  border-collapse: collapse;
}
.cgm-kv td {
  padding: 7px 0;
  font-size: 10.5px;
  vertical-align: top;
}
.cgm-kv .k {
  width: 42%;
  color: #8b1a1a;
  font-weight: 700;
  padding-right: 10px;
}
.cgm-kv .v {
  width: 58%;
  color: #171717;
  font-weight: 700;
}

.cgm-items {
  width: 100%;
  border-collapse: collapse;
  margin: 0 0 22px;
  table-layout: fixed;
}
.cgm-items thead tr th {
  background: #8b1a1a;
  color: #fff;
  padding: 8px 10px;
  text-align: left;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.4px;
}
.cgm-items thead tr th.num { text-align: right; }
.cgm-items tbody tr td {
  padding: 8px 10px;
  font-size: 10.5px;
  vertical-align: top;
  border-bottom: 1px solid #ececec;
  color: #171717;
}
.cgm-items tbody tr td.num {
  text-align: right;
  white-space: nowrap;
}
.cgm-items tbody tr:nth-child(even) td { background: #fafafa; }
.cgm-items tbody tr:last-child td { border-bottom: 1px solid #ddd; }

.cgm-bottom {
  width: 100%;
  border-collapse: collapse;
  margin: 0 0 8px;
  table-layout: fixed;
}
.cgm-bottom > tbody > tr > td {
  vertical-align: top;
  padding: 0;
}
.cgm-bottom .col-left {
  width: 52%;
  padding-right: 36px;
}
.cgm-bottom .col-right {
  width: 48%;
  padding-left: 8px;
}

.cgm-terms {
  margin: 0;
  padding: 0;
  font-size: 10.5px;
  line-height: 1.65;
  color: #444;
}
.cgm-terms .terms-title {
  display: block;
  margin: 0 0 6px;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 1px;
  text-transform: uppercase;
  color: #8b1a1a;
}

.cgm-qr {
  margin-top: 22px;
  width: 148px;
}
.cgm-qr img,
.cgm-qr svg {
  display: block;
  width: 148px;
  height: 148px;
}
.cgm-qr .qr-label {
  width: 148px;
  margin-top: 6px;
  font-size: 8.5px;
  color: #8b1a1a;
  text-transform: uppercase;
  letter-spacing: 1px;
  text-align: center;
  font-weight: 700;
}

.cgm-totals {
  width: 100%;
  border-collapse: collapse;
}
.cgm-totals td {
  padding: 10px 0;
  font-size: 11.5px;
}
.cgm-totals .t-label {
  color: #8b1a1a;
  font-weight: 700;
  text-align: left;
}
.cgm-totals .t-value {
  color: #171717;
  font-weight: 700;
  text-align: right;
  white-space: nowrap;
}
.cgm-totals .total-row td {
  padding-top: 14px;
  border-top: 1.5px solid #171717;
  font-size: 14px;
  font-weight: 800;
  color: #171717;
}
.cgm-totals .total-row .t-label {
  color: #8b1a1a;
  font-weight: 800;
  letter-spacing: 0.8px;
  text-transform: uppercase;
}
.cgm-totals .total-row .t-value {
  font-size: 15px;
  font-weight: 800;
  color: #171717;
}

.cgm-in-words {
  margin: 12px 0 0;
  font-size: 10px;
  color: #555;
  line-height: 1.5;
}

.cgm-thanks {
  margin: 30px 0 0;
  padding: 10px 0 0;
  text-align: center;
  font-size: 15px;
  font-weight: 700;
  color: #171717;
  letter-spacing: 0.2px;
}

.cgm-doc-footer {
  margin-top: 36px;
  padding-top: 10px;
}
</style>

<div class="cgm-inv">

  <table class="cgm-header">
    <tr>
      <td style="width:48%;">
        <h1 class="title">Invoice</h1>
      </td>
      <td style="width:52%;">
        <table class="cgm-meta-table">
          <tr>
            <td class="lbl">Date</td>
            <td class="val">{{ frappe.utils.format_date(doc.posting_date, "dd-MM-yyyy") }}</td>
          </tr>
          <tr>
            <td class="lbl">Invoice No</td>
            <td class="val">{{ doc.name }}</td>
          </tr>
        </table>
      </td>
    </tr>
  </table>

  <hr class="cgm-rule">

  <table class="cgm-parties">
    <tr>
      <td>
        <div class="cgm-section-label">Consignee</div>
        <div class="cgm-party-name">{{ doc.customer_name }}</div>
        {% if customer_address %}
          {% if customer_address.address_line1 %}<div class="cgm-party-line">{{ customer_address.address_line1 }}</div>{% endif %}
          {% if customer_address.address_line2 %}<div class="cgm-party-line">{{ customer_address.address_line2 }}</div>{% endif %}
          {% if customer_address.city or customer_address.pincode %}
          <div class="cgm-party-line">{{ customer_address.city or "" }}{% if customer_address.city and customer_address.pincode %} - {% endif %}{{ customer_address.pincode or "" }}</div>
          {% endif %}
          {% if customer_address.country %}<div class="cgm-party-line">{{ customer_address.country }}</div>{% endif %}
          {% if customer_address.phone %}<div class="cgm-party-line">Phone: {{ customer_address.phone }}</div>{% elif doc.contact_mobile %}<div class="cgm-party-line">Phone: {{ doc.contact_mobile }}</div>{% elif contact and contact.mobile_no %}<div class="cgm-party-line">Phone: {{ contact.mobile_no }}</div>{% endif %}
          {% if customer_address.email_id %}<div class="cgm-party-line">Email: {{ customer_address.email_id }}</div>{% elif doc.contact_email %}<div class="cgm-party-line">Email: {{ doc.contact_email }}</div>{% elif contact and contact.email_id %}<div class="cgm-party-line">Email: {{ contact.email_id }}</div>{% endif %}
        {% elif doc.custom_consignee_address %}
          <div class="cgm-party-line">{{ doc.custom_consignee_address | replace("\n", "<br>") }}</div>
          {% if doc.contact_mobile %}<div class="cgm-party-line">Phone: {{ doc.contact_mobile }}</div>{% elif contact and contact.mobile_no %}<div class="cgm-party-line">Phone: {{ contact.mobile_no }}</div>{% endif %}
          {% if doc.contact_email %}<div class="cgm-party-line">Email: {{ doc.contact_email }}</div>{% elif contact and contact.email_id %}<div class="cgm-party-line">Email: {{ contact.email_id }}</div>{% endif %}
        {% elif doc.address_display %}
          <div class="cgm-party-line">{{ doc.address_display }}</div>
          {% if doc.contact_mobile %}<div class="cgm-party-line">Phone: {{ doc.contact_mobile }}</div>{% elif contact and contact.mobile_no %}<div class="cgm-party-line">Phone: {{ contact.mobile_no }}</div>{% endif %}
          {% if doc.contact_email %}<div class="cgm-party-line">Email: {{ doc.contact_email }}</div>{% elif contact and contact.email_id %}<div class="cgm-party-line">Email: {{ contact.email_id }}</div>{% endif %}
        {% else %}
          {% if doc.contact_mobile %}<div class="cgm-party-line">Phone: {{ doc.contact_mobile }}</div>{% elif contact and contact.mobile_no %}<div class="cgm-party-line">Phone: {{ contact.mobile_no }}</div>{% endif %}
          {% if doc.contact_email %}<div class="cgm-party-line">Email: {{ doc.contact_email }}</div>{% elif contact and contact.email_id %}<div class="cgm-party-line">Email: {{ contact.email_id }}</div>{% endif %}
        {% endif %}
      </td>
      <td>
        <div class="cgm-section-label">Invoice Address</div>
        <div class="cgm-party-name">{{ doc.company }}</div>
        {% if company_address %}
          {% if company_address.address_line1 %}<div class="cgm-party-line">{{ company_address.address_line1 }}</div>{% endif %}
          {% if company_address.address_line2 %}<div class="cgm-party-line">{{ company_address.address_line2 }}</div>{% endif %}
          {% if company_address.city or company_address.pincode %}
          <div class="cgm-party-line">{{ company_address.city or "" }}{% if company_address.city and company_address.pincode %} - {% endif %}{{ company_address.pincode or "" }}</div>
          {% endif %}
          {% if company_address.country %}<div class="cgm-party-line">{{ company_address.country }}</div>{% endif %}
          {% if company_address.phone %}<div class="cgm-party-line">Phone: {{ company_address.phone }}</div>{% endif %}
          {% if company_address.email_id %}<div class="cgm-party-line">Email: {{ company_address.email_id }}</div>{% endif %}
        {% elif doc.company_address_display %}
          <div class="cgm-party-line">{{ doc.company_address_display }}</div>
        {% endif %}
      </td>
    </tr>
  </table>

  <div class="cgm-shipment-wrap">
    <table class="cgm-shipment">
      <tr>
        <td>
          <table class="cgm-kv">
            <tr>
              <td class="k">Shipment</td>
              <td class="v">{{ doc.project or "" }}</td>
            </tr>
            <tr>
              <td class="k">Country of Origin</td>
              <td class="v">{{ doc.custom_country_of_origin or "" }}</td>
            </tr>
            <tr>
              <td class="k">Due Date</td>
              <td class="v">{% if doc.due_date %}{{ frappe.utils.format_date(doc.due_date, "dd-MM-yyyy") }}{% endif %}</td>
            </tr>
          </table>
        </td>
        <td>
          <table class="cgm-kv">
            <tr>
              <td class="k">Our Ref No</td>
              <td class="v">{{ doc.custom_cgm_reference_no or "" }}</td>
            </tr>
            <tr>
              <td class="k">IDF No</td>
              <td class="v">{{ doc.custom_idfno or "" }}</td>
            </tr>
            <tr>
              <td class="k">Client Ref No</td>
              <td class="v">{{ doc.custom_client_reference_no or "" }}</td>
            </tr>
          </table>
        </td>
      </tr>
    </table>
  </div>

  <table class="cgm-items">
    <thead>
      <tr>
        <th style="width:52%;">Item Descriptions</th>
        <th class="num" style="width:12%;">Qty</th>
        <th class="num" style="width:18%;">Rate</th>
        <th class="num" style="width:18%;">Amount</th>
      </tr>
    </thead>
    <tbody>
      {% for item in doc.items %}
      <tr>
        <td>{{ item.description or item.item_name }}</td>
        <td class="num">{{ item.get_formatted("qty", doc) }}</td>
        <td class="num">{{ item.get_formatted("rate", doc) }}</td>
        <td class="num">{{ item.get_formatted("amount", doc) }}</td>
      </tr>
      {% endfor %}
    </tbody>
  </table>

  <table class="cgm-bottom">
    <tr>
      <td class="col-left">
        {% if doc.terms %}
        <div class="cgm-terms">
          <span class="terms-title">Terms</span>
          {{ doc.terms }}
        </div>
        {% endif %}

        <div class="cgm-qr">
          {% if _ns.qr_b64 %}
            <img src="data:image/png;base64,{{ _ns.qr_b64 }}"
                 width="148" height="148" alt="Scan to Verify"
                 style="display:block; width:148px; height:148px; object-fit:contain;">
          {% else %}
            <svg xmlns="http://www.w3.org/2000/svg" width="148" height="148" viewBox="0 0 80 80" style="display:block; width:148px; height:148px;">
              <rect width="80" height="80" fill="white" stroke="#e0e0e0" stroke-width="0.5"/>
              <rect x="4"  y="4"  width="28" height="28" fill="none" stroke="#8b1a1a" stroke-width="2.5" rx="2"/>
              <rect x="9"  y="9"  width="18" height="18" fill="#8b1a1a" rx="1"/>
              <rect x="48" y="4"  width="28" height="28" fill="none" stroke="#8b1a1a" stroke-width="2.5" rx="2"/>
              <rect x="53" y="9"  width="18" height="18" fill="#8b1a1a" rx="1"/>
              <rect x="4"  y="48" width="28" height="28" fill="none" stroke="#8b1a1a" stroke-width="2.5" rx="2"/>
              <rect x="9"  y="53" width="18" height="18" fill="#8b1a1a" rx="1"/>
              <rect x="40" y="40" width="6" height="6" fill="#8b1a1a"/>
              <rect x="49" y="40" width="6" height="6" fill="#8b1a1a"/>
              <rect x="58" y="40" width="6" height="6" fill="#8b1a1a"/>
              <rect x="67" y="40" width="6" height="6" fill="#8b1a1a"/>
              <rect x="40" y="49" width="6" height="6" fill="#8b1a1a"/>
              <rect x="58" y="49" width="6" height="6" fill="#8b1a1a"/>
              <rect x="40" y="58" width="6" height="6" fill="#8b1a1a"/>
              <rect x="49" y="58" width="6" height="6" fill="#8b1a1a"/>
              <rect x="67" y="58" width="6" height="6" fill="#8b1a1a"/>
              <rect x="40" y="67" width="6" height="6" fill="#8b1a1a"/>
              <rect x="58" y="67" width="6" height="6" fill="#8b1a1a"/>
              <rect x="67" y="67" width="6" height="6" fill="#8b1a1a"/>
            </svg>
          {% endif %}
          <div class="qr-label">Scan to Verify</div>
        </div>
      </td>
      <td class="col-right">
        <table class="cgm-totals">
          <tr>
            <td class="t-label">Subtotal</td>
            <td class="t-value">{{ doc.get_formatted("net_total") }}</td>
          </tr>
          {% set vat_shown = namespace(ok=false) %}
          {% for tax in doc.taxes or [] %}
            {% if tax.tax_amount %}
            <tr>
              <td class="t-label">{{ tax.description or "VAT" }}</td>
              <td class="t-value">{{ tax.get_formatted("tax_amount") }}</td>
            </tr>
            {% set vat_shown.ok = true %}
            {% endif %}
          {% endfor %}
          {% if not vat_shown.ok %}
          <tr>
            <td class="t-label">VAT</td>
            <td class="t-value"></td>
          </tr>
          {% endif %}
          <tr class="total-row">
            <td class="t-label">Total</td>
            <td class="t-value">{{ doc.get_formatted("grand_total") }}</td>
          </tr>
        </table>
        {% if doc.in_words %}
        <p class="cgm-in-words"><strong>In Words:</strong> {{ doc.in_words }}</p>
        {% endif %}
      </td>
    </tr>
  </table>

  <div class="cgm-thanks">Thank you for your business.</div>

</div>

{%- if footer -%}
<div class="cgm-doc-footer">{{ footer }}</div>
{%- endif -%}
